/**
 * geminiService.js — Gemini API client for the AI Template Builder
 *
 * Talks to either:
 *   1. A Cloudflare Worker proxy (REACT_APP_GEMINI_WORKER_URL), or
 *   2. The Gemini API directly (REACT_APP_GEMINI_KEY) — dev/demo fallback
 *
 * All calls use Gemini 3.5 Flash (multimodal: text + images).
 */

const WORKER_URL = process.env.REACT_APP_GEMINI_WORKER_URL || '';
const DIRECT_KEY = process.env.REACT_APP_GEMINI_KEY || '';
const MODEL = 'gemini-3.5-flash';

// ---------------------------------------------------------------------------
// System prompt — encodes template schema + domain context
// ---------------------------------------------------------------------------

