const DEFAULT_ACK = 'Understood. I will generate valid LiTeCAB template JSON based on your input.';

// ---------------------------------------------------------------------------
// Build Gemini-format contents array from chat history
// ---------------------------------------------------------------------------

function buildContents(messages, systemPrompt = SYSTEM_PROMPT, systemAck = DEFAULT_ACK) {
  // messages: [{ role: 'user'|'assistant', text?, imageBase64?, imageMime? }]
  const contents = [];

  // System instruction as the first "user" turn (Gemini format)
  contents.push({
    role: 'user',
    parts: [{ text: systemPrompt }],
  });
  contents.push({
    role: 'model',
    parts: [{ text: systemAck }],
  });

  for (const msg of messages) {
    const parts = [];
    if (msg.text) parts.push({ text: msg.text });
    if (msg.imageBase64 && msg.imageMime) {
      parts.push({
        inlineData: { mimeType: msg.imageMime, data: msg.imageBase64 },
      });
    }
    if (parts.length > 0) {
      contents.push({
        role: msg.role === 'assistant' ? 'model' : 'user',
        parts,
      });
    }
  }

  return contents;
}

// ---------------------------------------------------------------------------
// Call Gemini (via Worker proxy or direct)
// ---------------------------------------------------------------------------

export async function callGemini(messages, options = {}) {
  const { systemPrompt = SYSTEM_PROMPT, systemAck = DEFAULT_ACK, generationConfig } = options;
  const contents = buildContents(messages, systemPrompt, systemAck);
  const payload = {
    contents,
    generationConfig: generationConfig || {
      temperature: 0.2,
      responseMimeType: 'application/json',
    },
  };

  let url;
  if (WORKER_URL) {
    url = WORKER_URL;
  } else if (DIRECT_KEY) {
    url = `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${DIRECT_KEY}`;
  } else {
    throw new Error('No Gemini API configuration found. Set REACT_APP_GEMINI_WORKER_URL or REACT_APP_GEMINI_KEY.');
  }

  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!resp.ok) {
    const errText = await resp.text();
    if (resp.status === 429) {
      throw new Error('Rate limited — please wait a moment and try again.');
    }
    throw new Error(`Gemini API error (${resp.status}): ${errText}`);
  }

  const data = await resp.json();

  // Extract text from Gemini response
  const text =
    data?.candidates?.[0]?.content?.parts?.[0]?.text ||
    data?.candidates?.[0]?.content?.parts
      ?.filter((p) => p.text)
      .map((p) => p.text)
      .join('') ||
    '';

  if (!text) {
    throw new Error('Empty response from Gemini.');
  }

  return text;
}

// ---------------------------------------------------------------------------
// Parse Gemini response text into a template object
// ---------------------------------------------------------------------------

export function parseTemplateResponse(text) {
  // Strip markdown fences if Gemini included them despite instructions
  let clean = text.trim();
  if (clean.startsWith('```')) {
    clean = clean.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
  }

  const template = JSON.parse(clean);

  // Basic validation
  if (!template.project_name) throw new Error('Missing project_name in generated template.');
  if (!template.processes || Object.keys(template.processes).length === 0) {
    throw new Error('Generated template has no processes.');
  }

  return template;
}
